function attempt(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

async function attemptAsync(operation) {
  try {
    await operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function attemptPermissionDenied(operation) {
  try {
    operation();
    return "LEAKED";
  } catch (error) {
    return error instanceof Deno.errors.NotCapable ||
        error instanceof Deno.errors.PermissionDenied
      ? "DENIED"
      : "BROKEN";
  }
}

async function attemptPermissionDeniedAsync(operation) {
  const outcome = Promise.resolve().then(operation).then(
    () => "LEAKED",
    (error) =>
      error instanceof Deno.errors.NotCapable ||
        error instanceof Deno.errors.PermissionDenied
        ? "DENIED"
        : "BROKEN",
  );
  let timeoutId;
  const timeout = new Promise((resolve) => {
    timeoutId = setTimeout(() => resolve("HUNG"), 250);
  });
  const result = await Promise.race([outcome, timeout]);
  clearTimeout(timeoutId);
  return result;
}

function deniedGcProfilerStart() {
  const profiler = new v8.GCProfiler();
  const result = attemptPermissionDenied(() => profiler.start());
  if (result === "LEAKED") {
    try {
      profiler.stop();
    } catch {
      return "BROKEN";
    }
  }
  return result;
}

function waitForSuccess(child) {
  return new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("exit", (code, signal) => {
      if (code === 0) resolve();
      else reject(new Error(`child failed: code=${code} signal=${signal}`));
    });
  });
}

function waitForExit(child) {
  return new Promise((resolve) => {
    child.once("exit", (code, signal) => resolve({ code, signal }));
  });
}

function directSignalResult(child) {
  try {
    child.kill("SIGTERM");
    return "LEAKED";
  } catch {
    return "DENIED";
  }
}

// @ref LLP 0010#revision-11-patch-profile [tests] — Package signaling stays denied while non-exported timeout/abort cleanup remains live.
// @ref LLP 0019#operation-scoped-positive-authority-provenance [tests] — Cleanup can terminate only the child represented by the retained resource.
async function verifyOwnedChildCleanup(kind) {
  const controller = kind === "abort" ? new AbortController() : null;
  const child = childProcess.spawn(
    Deno.execPath(),
    ["eval", "setTimeout(() => {}, 750)"],
    {
      stdio: "ignore",
      ...(kind === "timeout" ? { timeout: 50 } : { signal: controller.signal }),
    },
  );
  const exit = waitForExit(child);
  let abortError = null;
  child.on("error", (error) => {
    abortError = error;
  });

  const directSignal = directSignalResult(child);
  if (controller !== null) controller.abort();
  const status = await exit;
  const terminated = status.code === null && status.signal === "SIGTERM" &&
    child.killed === true;
  const expectedError = kind !== "abort" || abortError?.name === "AbortError";

  return {
    directSignal,
    cleanup: terminated && expectedError ? "ALLOWED" : "DENIED",
  };
}

async function verifyNodeDisposeCleanup() {
  const child = childProcess.spawn(
    Deno.execPath(),
    ["eval", "setTimeout(() => {}, 750)"],
    { stdio: "ignore" },
  );
  const exit = waitForExit(child);
  child[Symbol.dispose]();
  const status = await exit;
  return status.code === null && status.signal === "SIGTERM" && child.killed
    ? "ALLOWED"
    : "DENIED";
}

async function verifyDenoCleanup(kind) {
  const controller = kind === "dispose" ? null : new AbortController();
  const command = new Deno.Command(Deno.execPath(), {
    args: ["eval", "setTimeout(() => {}, 750)"],
    stdout: "null",
    stderr: "null",
    ...(controller === null ? {} : { signal: controller.signal }),
  });

  if (kind === "output") {
    const output = command.output();
    controller.abort();
    const status = await output;
    return {
      directSignal: null,
      cleanup: !status.success && status.signal === "SIGTERM"
        ? "ALLOWED"
        : "DENIED",
    };
  }

  const child = command.spawn();
  let directSignal = null;
  if (kind === "dispose") {
    await child[Symbol.asyncDispose]();
  } else {
    directSignal = attemptPermissionDenied(() => child.kill("SIGTERM"));
    controller.abort();
  }
  const status = await child.status;
  return {
    directSignal,
    cleanup: !status.success && status.signal === "SIGTERM"
      ? "ALLOWED"
      : "DENIED",
  };
}

async function verifyExecCleanup(api, trigger) {
  const script = trigger === "maxBuffer"
    ? 'console.log("overflow"); setTimeout(() => {}, 750)'
    : "setTimeout(() => {}, 750)";
  const options = trigger === "maxBuffer" ? { maxBuffer: 1 } : { timeout: 50 };
  let finishCallback;
  const callback = new Promise((resolve) => {
    finishCallback = resolve;
  });
  const onComplete = (error) => finishCallback(error);
  const child = api === "execFile"
    ? childProcess.execFile(
      Deno.execPath(),
      ["eval", script],
      options,
      onComplete,
    )
    : childProcess.exec(
      `${JSON.stringify(Deno.execPath())} eval ${JSON.stringify(script)}`,
      options,
      onComplete,
    );
  const exit = waitForExit(child);
  const directSignal = directSignalResult(child);
  const [status, error] = await Promise.all([exit, callback]);
  const terminated = status.code === null && status.signal === "SIGTERM" &&
    child.killed === true;
  const expectedError = trigger === "maxBuffer"
    ? error?.code === "ERR_CHILD_PROCESS_STDIO_MAXBUFFER"
    : error?.killed === true && error?.signal === "SIGTERM";

  return {
    directSignal,
    cleanup: terminated && expectedError ? "ALLOWED" : "DENIED",
  };
}

